package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("007"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber(".45"));
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse("Two decimal points", NumberUtils.isNumber("1.2.3"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("1e2.3"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1e-10"));
        assertTrue(NumberUtils.isNumber("1E+10"));
        assertTrue(NumberUtils.isNumber("-1e10"));
        assertFalse("E without digit before", NumberUtils.isNumber("e10"));
        assertFalse("E at the end", NumberUtils.isNumber("123e"));
        assertFalse("Two E's", NumberUtils.isNumber("1e2e3"));
        assertFalse("Sign without digit after E", NumberUtils.isNumber("1e+"));
        assertFalse("E with decimal in exponent", NumberUtils.isNumber("1e2.3"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("-0x123"));
        assertFalse("Just 0x", NumberUtils.isNumber("0x"));
        assertFalse("Hex with non-hex char", NumberUtils.isNumber("0x12g"));
        assertFalse("Hex with decimal", NumberUtils.isNumber("0x1.2"));
    }

    @Test
    public void testIsNumber_Suffixes() {
        // d, D, f, F suffixes
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        // l, L suffixes
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // Fail cases for suffixes
        assertFalse("L with exponent", NumberUtils.isNumber("1e10L"));
        assertFalse("L with exponent lowercase", NumberUtils.isNumber("1E10l"));
    }

    @Test
    public void testIsNumber_EdgeCasesAndInvalid() {
        assertFalse("Just a dot", NumberUtils.isNumber("."));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a sign and dot", NumberUtils.isNumber("-."));
        assertFalse("Invalid characters", NumberUtils.isNumber("12a3"));
        assertFalse("Space in middle", NumberUtils.isNumber("12 3"));
        assertFalse("Leading space", NumberUtils.isNumber(" 123"));
        assertFalse("Trailing space", NumberUtils.isNumber("123 "));
        assertFalse("Special characters", NumberUtils.isNumber("!@#"));
    }

    @Test
    public void testIsNumber_BranchCoverageSpecifics() {
        // Testing the logic: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This covers the case where a sign follows an 'E' but no digit has been found yet
        assertTrue(NumberUtils.isNumber("1e+2"));

        // Testing the branch: if (chars[i] >= '.')
        // Single trailing decimal point after non-exponent is ok if foundDigit is true
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber(".")); // foundDigit is false

        // Testing the branch: if (!allowSigns && (chars[i] == 'd' ...))
        assertTrue(NumberUtils.isNumber("123f"));
    }
}
